// capi.js  (Node 18+). Runs on YOUR SERVER only, never in the browser.
const crypto = require('crypto');
const sha256 = (v) => crypto.createHash('sha256')
  .update(String(v).trim().toLowerCase()).digest('hex');

async function sendToMeta(event) {
  const url = `https://graph.facebook.com/${process.env.META_API_VERSION}` +
    `/${process.env.META_PIXEL_ID}/events?access_token=${process.env.META_TOKEN}`;
  const body = { data: [event] };
  if (process.env.META_TEST_CODE) body.test_event_code = process.env.META_TEST_CODE;
  const res = await fetch(url, { method: 'POST',
    headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
  const json = await res.json();
  if (!res.ok) console.error('Meta rejected event', json);   // log and fix
  return json;
}

