// On your lander, runs once when the page loads.
(function () {
  var p = new URLSearchParams(location.search);
  var fbp = (document.cookie.match(/_fbp=([^;]+)/) || [])[1] || '';
  window.clickId = 'c_' + crypto.randomUUID().slice(0, 8);

  // 1. Tell your server about the click (it adds IP + user agent).
  navigator.sendBeacon('/api/click', JSON.stringify({
    click_id: window.clickId, fbclid: p.get('fbclid'), fbp: fbp,
    campaign: p.get('utm_campaign'), adset: p.get('adset'),
    ad: p.get('ad'), url: location.href, time_ms: Date.now()
  }));

  // 2. Put the click ID into the offer link as sub1.
  var link = 'https://network.example/click?offer=123&aff=456'
    + '&sub1=' + encodeURIComponent(window.clickId)
    + '&sub2=' + encodeURIComponent(p.get('utm_campaign') || '')
    + '&sub3=' + encodeURIComponent(p.get('adset') || '');
  document.getElementById('join-btn').href = link;
})();

