// pb.js  (Node + Express). The network calls this URL.
app.get('/pb', async (req, res) => {
  const { key, cid, event, payout, currency, status, txid } = req.query;
  if (key !== process.env.PB_KEY) return res.status(403).send('bad key');
  await db.postbacks.insert({ ...req.query, at: new Date() }); // raw log first

  const click = await db.clicks.findOne({ click_id: cid });
  if (!click) return res.send('ok');                 // log only: unknown click
  if (status !== 'approved') return res.send('ok');  // your network's word may differ

  const isFtd = event === 'ftd';
  await sendToMeta({                                 // from lesson 4
    event_name: isFtd ? 'Purchase' : 'CompleteRegistration',
    event_time: Math.floor(Date.now() / 1000),
    event_id: `${event}_${txid}`,                    // retries keep the same ID
    action_source: 'website',
    event_source_url: click.url,
    user_data: { fbc: click.fbc, fbp: click.fbp,
      client_ip_address: click.ip, client_user_agent: click.ua,
      external_id: [sha256(click.click_id)] },
    custom_data: isFtd ? { value: Number(payout), currency: currency || 'USD' } : {}
  });
  res.send('ok');                                    // answer fast with 200
});

