// Telegram webhook (Node + Express). The bot is an admin of the channel.
app.post('/tg/webhook', async (req, res) => {
  if (req.get('X-Telegram-Bot-Api-Secret-Token') !== process.env.TG_SECRET)
    return res.sendStatus(403);
  res.sendStatus(200);                                   // answer Telegram fast
  const r = req.body.chat_join_request;
  if (!r) return;

  const clickId = r.invite_link && r.invite_link.name;   // links named by click ID
  await tg('approveChatJoinRequest', { chat_id: r.chat.id, user_id: r.from.id });
  await db.joins.insert({ click_id: clickId, tg_user: r.from.id, at: r.date });

  const click = clickId && await db.clicks.findOne({ click_id: clickId });
  if (!click) return;                                    // logged, not sent
  await sendToMeta({                                     // from lesson 4
    event_name: 'Lead',                                  // your plan's join event
    event_time: r.date,                                  // already in seconds
    event_id: `join_${clickId}`,
    action_source: 'website',
    event_source_url: click.url,
    user_data: { fbc: click.fbc, fbp: click.fbp,
      client_ip_address: click.ip, client_user_agent: click.ua,
      external_id: [sha256(clickId)] }
  });
});
